import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p69_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv_transpose2d_fastpath(torch::Tensor input, torch::Tensor weight);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose2d_fastpath", &conv_transpose2d_fastpath, "Specialized ConvTranspose2d fast path");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Specialized kernel for N=64, Cin=64, Cout=128, HxW=128x256, K=3x5, stride=1, padding=0
// Reduced register pressure by tiling output width and unrolling kernel taps

template<int TILE_W>
__global__ void conv_transpose2d_kernel_3x5(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int Cin, int H, int W,
    int Cout, int Ho, int Wo)
{
    const int kh = 3;
    const int kw = 5;

    int wo_base = blockIdx.x * TILE_W;
    int ho = blockIdx.y;
    int oc = blockIdx.z;
    int n = blockIdx.z / Cout;
    oc = blockIdx.z % Cout;

    if (n >= N || oc >= Cout || ho >= Ho) return;

    float accum[TILE_W];
    #pragma unroll
    for (int tw = 0; tw < TILE_W; tw++) {
        accum[tw] = 0.0f;
    }

    for (int ic = 0; ic < Cin; ic++) {
        #pragma unroll
        for (int dkh = 0; dkh < kh; dkh++) {
            int ih = ho - dkh;
            if (ih < 0 || ih >= H) continue;

            #pragma unroll
            for (int dkw = 0; dkw < kw; dkw++) {
                float w_val = weight[((ic * Cout + oc) * kh + dkh) * kw + dkw];

                #pragma unroll
                for (int tw = 0; tw < TILE_W; tw++) {
                    int wo = wo_base + tw;
                    if (wo >= Wo) continue;
                    int iw = wo - dkw;
                    if (iw >= 0 && iw < W) {
                        float in_val = input[((n * Cin + ic) * H + ih) * W + iw];
                        accum[tw] += in_val * w_val;
                    }
                }
            }
        }
    }

    #pragma unroll
    for (int tw = 0; tw < TILE_W; tw++) {
        int wo = wo_base + tw;
        if (wo < Wo) {
            output[((n * Cout + oc) * Ho + ho) * Wo + wo] = accum[tw];
        }
    }
}

torch::Tensor conv_transpose2d_fastpath(
    torch::Tensor input,
    torch::Tensor weight)
{
    const int N = input.size(0);
    const int Cin = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    const int Cout = weight.size(1);
    const int kh = weight.size(2);
    const int kw = weight.size(3);

    const int Ho = H + kh - 1;
    const int Wo = W + kw - 1;

    auto output = torch::zeros({N, Cout, Ho, Wo}, input.options());

    const int TILE_W = 8;
    dim3 grid((Wo + TILE_W - 1) / TILE_W, Ho, N * Cout);
    dim3 block(1);

    conv_transpose2d_kernel_3x5<8><<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, Cin, H, W, Cout, Ho, Wo
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a transposed 2D convolution operation with asymmetric input and kernel size.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (tuple): Tuple of integers representing the kernel size (height, width).
            stride (tuple, optional): Tuple of integers representing the stride of the convolution. Defaults to (1, 1).
            padding (tuple, optional): Tuple of integers representing the padding applied to the input. Defaults to (0, 0).
            output_padding (tuple, optional): Tuple of integers representing the additional size added to one side of the output shape. Defaults to (0, 0).
            dilation (tuple, optional): Tuple of integers representing the spacing between kernel elements. Defaults to (1, 1).
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), output_padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose2d = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, dilation=dilation, groups=groups, bias=bias)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Fast-path for benchmark defaults: N=64, Cin=64, Cout=128, HxW=128x256, K=3x5
        # stride=1, padding=0, dilation=1, groups=1, bias=False
        if (x.is_cuda and x.is_contiguous() and x.dtype == torch.float32 and
            self.conv_transpose2d.stride == (1, 1) and
            self.conv_transpose2d.padding == (0, 0) and
            self.conv_transpose2d.output_padding == (0, 0) and
            self.conv_transpose2d.dilation == (1, 1) and
            self.conv_transpose2d.groups == 1 and
            self.conv_transpose2d.bias is None and
            self.conv_transpose2d.kernel_size == (3, 5)):
            return _stark_get_extension().conv_transpose2d_fastpath(x, self.conv_transpose2d.weight)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return self.conv_transpose2d(x)
        # <<<END_IMPROVE>>>

