// output[n, oc, oh, ow] = sum_{ic,kh,kw} input[n,ic,oh-kh,ow-kw] * weight[ic,oc,kh,kw]
// where oh in [0, H+Kh-2], ow in [0, W+Kw-2]
// weight layout: [Cin, Cout, Kh, Kw]
