#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Tiled implicit-GEMM transposed convolution kernel.
// output[n, oc, oh, ow] = sum_{ic, kh, kw} input[n, ic, oh-kh*dil_h, ow-kw*dil_w] * weight[ic, oc, kh, kw]
// where indices are valid (0 <= oh-kh*dil_h-pad_h_adjusted < H etc.)
// For stride=1, padding=0: ih = oh - kh, iw = ow - kw, valid when 0<=ih<H, 0<=iw<W

// Block tiles: OC_TILE output channels x SPATIAL_TILE spatial positions
// Each thread handles one (oc_local, sp_local) output element
// Shared memory stages weight slice [IC_CHUNK x Kh x Kw] for OC_TILE channels

#define KH 3
#define KW 5
#define KHW 15

// Tile dimensions
#define OC_TILE 32
#define SP_TILE 8    // spatial positions per block
#define IC_STEP 8    // input channels processed per shared-mem load

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int Cin, int H, int W,
    int Cout, int Ho, int Wo,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w)
{
    // Grid: x=ceil(Ho*Wo/SP_TILE), y=ceil(Cout/OC_TILE), z=N
    int sp_base = blockIdx.x * SP_TILE;
    int oc_base = blockIdx.y * OC_TILE;
    int n       = blockIdx.z;

    int sp_local = threadIdx.x;   // 0..SP_TILE-1
    int oc_local = threadIdx.y;   // 0..OC_TILE-1

    int oc = oc_base + oc_local;
    int sp = sp_base + sp_local;

    int oh = sp / Wo;
    int ow = sp % Wo;

    float acc = 0.0f;

    bool valid_out = (oc < Cout) && (oh < Ho) && (ow < Wo) && (n < N);

    // shared memory: weight slice [OC_TILE][IC_STEP][KH][KW]
    // and input slice [IC_STEP][KH][KW] for the current spatial set
    // We store weights as [IC_STEP][OC_TILE][KH][KW] for better oc-axis reuse
    __shared__ float smem_w[IC_STEP][OC_TILE][KHW];  // [ic_chunk][oc][kh*kw]

    for (int ic_base = 0; ic_base < Cin; ic_base += IC_STEP) {
        int ic_end = min(ic_base + IC_STEP, Cin);

        // Load weight tile: weight layout is [Cin, Cout, Kh, Kw]
        // Each thread loads some elements
        int tid = oc_local * SP_TILE + sp_local;
        int total_w = IC_STEP * OC_TILE * KHW;
        for (int i = tid; i < total_w; i += OC_TILE * SP_TILE) {
            int ic_rel = i / (OC_TILE * KHW);
            int rem    = i % (OC_TILE * KHW);
            int oc_idx = oc_base + rem / KHW;
            int khw    = rem % KHW;
            int ic_abs = ic_base + ic_rel;
            if (ic_abs < Cin && oc_idx < Cout) {
                smem_w[ic_rel][rem / KHW][khw] = weight[ic_abs * Cout * KHW + oc_idx * KHW + khw];
            } else {
                smem_w[ic_rel][rem / KHW][khw] = 0.0f;
            }
        }
        __syncthreads();

        if (valid_out) {
            #pragma unroll
            for (int ic_rel = 0; ic_rel < IC_STEP; ic_rel++) {
                int ic_abs = ic_base + ic_rel;
                if (ic_abs >= Cin) break;

                #pragma unroll
                for (int kh = 0; kh < KH; kh++) {
                    int ih = oh - kh * dil_h + pad_h;
                    if (ih < 0 || ih >= H) continue;
                    #pragma unroll
                    for (int kw = 0; kw < KW; kw++) {
                        int iw = ow - kw * dil_w + pad_w;
                        if (iw < 0 || iw >= W) continue;
                        float in_val = input[((n * Cin + ic_abs) * H + ih) * W + iw];
                        acc += in_val * smem_w[ic_rel][oc_local][kh * KW + kw];
                    }
                }
            }
        }
        __syncthreads();
    }

    if (valid_out) {
        output[((n * Cout + oc) * Ho + oh) * Wo + ow] = acc;
    }
